export default function prepare({ body, workflowColumn, stackColumn, messageColumn, dateColumn }) {
  const e = body?.execution,
    w = body?.workflow;
  if (
    !e ||
    e.id == null ||
    !e.error ||
    typeof e.error.message !== "string" ||
    typeof e.error.stack !== "string" ||
    typeof w?.name !== "string"
  )
    throw Error("Incomplete n8n error event");
  const keys = [workflowColumn, stackColumn, messageColumn, dateColumn];
  if (keys.some((x) => !x || x.startsWith("YOUR_")) || new Set(keys).size !== 4)
    throw Error("Configure four distinct Monday column IDs");
  return {
    name: String(e.id),
    values: {
      [workflowColumn]: w.name,
      [stackColumn]: { text: escape(e.error.stack) },
      [messageColumn]: e.error.message,
      [dateColumn]: new Date().toISOString(),
    },
  };
}

